154	                PreparedStatement select = connection.prepareStatement(
155	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
156	                ResultSet rows = select.executeQuery()) {
157	            List<Message> messages = new ArrayList<>();
158	            while (rows.next()) {
159	                messages.add(new Message(
160	                        rows.getLong("id"),
161	                        rows.getString("channel"),
162	                        rows.getString("recipient"),
163	                        rows.getString("subject"),
164	                        rows.getString("body")));
165	            }
166	            return messages;
167	        } catch (SQLException failure) {
168	            throw new IllegalStateException("could not read the sent messages", failure);
169	        }
170	    }
