186	/** Puts the inn's pieces together and runs the HTTP server. */
187	public final class Hotel {
188	
189	    private final Javalin server;
190	
191	    public Hotel(DataSource dataSource) {
192	        Rooms rooms = new Rooms(dataSource);
193	        ReservationStore store = new ReservationStore(dataSource);
194	        SentMessages sentMessages = new SentMessages(dataSource);
195	        ReservationService reservations =
196	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
197	        HttpApi api = new HttpApi(
198	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
199	        this.server = api.server();
200	    }
201	
202	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
203	    public int start(int port) {
204	        server.start(port);
205	        return server.port();
206	    }
207	
208	    public void stop() {
209	        server.stop();
210	    }
